using System.Security.Cryptography; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models;
namespace RaceDay.Api.Services;
public interface IPasswordService { string Hash(string password); bool Verify(string password,string hash); }
public class PasswordService:IPasswordService { public string Hash(string password){var salt=RandomNumberGenerator.GetBytes(16);var key=Rfc2898DeriveBytes.Pbkdf2(password,salt,120000,HashAlgorithmName.SHA256,32);return $"v1:{Convert.ToBase64String(salt)}:{Convert.ToBase64String(key)}";} public bool Verify(string password,string hash){try{var p=hash.Split(':');var key=Rfc2898DeriveBytes.Pbkdf2(password,Convert.FromBase64String(p[1]),120000,HashAlgorithmName.SHA256,32);return CryptographicOperations.FixedTimeEquals(key,Convert.FromBase64String(p[2]));}catch{return false;}} }
public class SessionAuth(RaceDayDbContext db,IHttpContextAccessor http){ public User? Current=>http.HttpContext?.Session.GetInt32("UserId") is int id?db.Users.Find(id):null; public bool Is(UserRole role)=>Current?.Role==role; public static UserResponse View(User u)=>new(u.Id,u.FullName,u.Email,u.Role,u.Phone,u.ProfileImageUrl); }
